window.IMPLEMENTATIONS_DATA = {
  "load-balancer-from-scratch": {
    "id": "load-balancer-from-scratch",
    "title": "Layer 7 Load Balancer From Scratch",
    "primarySlug": "load-balancers",
    "summary": "A tiny L7 request router with health checks, round-robin routing, least-connections routing, and forwarded request metadata.",
    "files": {
      "README.md": "# Layer 7 Load Balancer From Scratch\n\nA real HTTP reverse proxy demonstrating how traffic is distributed across backend target instances.\n\n### Key Concepts:\n1. **Health Checks**: Background probes that mark backends as healthy or degraded.\n2. **Round Robin**: Sequential circular dispatch among healthy nodes.\n3. **Least Connections**: Dispatches to the node currently servicing the fewest active requests.\n4. **Header Forwarding**: Preserves client IP with `X-Forwarded-For` and assigns unique request trace IDs.\n\n### Features:\n- Real HTTP server using Node.js `http` module\n- Automatic health probing with configurable interval\n- Round-robin and least-connections algorithms\n- Request forwarding to backend servers",
      "balancer.js": "const http = require('http');\nconst crypto = require('crypto');\n\nclass LoadBalancer {\n  constructor(targets, algorithm = 'round-robin', healthCheckIntervalMs = 10000) {\n    this.targets = targets.map(url => ({\n      url,\n      healthy: true,\n      activeConnections: 0,\n      totalHandled: 0,\n      lastHealthCheck: 0\n    }));\n    this.algorithm = algorithm;\n    this.currentIndex = 0;\n    this.healthCheckIntervalMs = healthCheckIntervalMs;\n    this.healthCheckTimer = null;\n    \n    // Start background health checks\n    this._startHealthChecks();\n  }\n\n  _startHealthChecks() {\n    if (this.healthCheckTimer) clearInterval(this.healthCheckTimer);\n    this.healthCheckTimer = setInterval(() => {\n      this._runHealthChecks();\n    }, this.healthCheckIntervalMs);\n    if (this.healthCheckTimer.unref) this.healthCheckTimer.unref();\n  }\n\n  _runHealthChecks() {\n    for (const target of this.targets) {\n      const url = new URL(target.url);\n      const req = http.request({\n        hostname: url.hostname,\n        port: url.port,\n        path: '/health',\n        method: 'GET',\n        timeout: 2000\n      }, (res) => {\n        target.healthy = res.statusCode === 200;\n        target.lastHealthCheck = Date.now();\n      });\n      req.on('error', () => {\n        target.healthy = false;\n        target.lastHealthCheck = Date.now();\n      });\n      req.on('timeout', () => {\n        target.healthy = false;\n        req.destroy();\n      });\n      req.end();\n    }\n  }\n\n  markHealth(url, isHealthy) {\n    const target = this.targets.find(t => t.url === url);\n    if (target) {\n      target.healthy = isHealthy;\n      target.lastHealthCheck = Date.now();\n    }\n  }\n\n  selectTarget() {\n    const healthyTargets = this.targets.filter(t => t.healthy);\n    if (healthyTargets.length === 0) {\n      throw new Error('503 Service Unavailable: No healthy backend targets');\n    }\n\n    if (this.algorithm === 'least-connections') {\n      return healthyTargets.reduce((prev, curr) => \n        curr.activeConnections < prev.activeConnections ? curr : prev\n      );\n    }\n\n    // Round-robin\n    const target = healthyTargets[this.currentIndex % healthyTargets.length];\n    this.currentIndex = (this.currentIndex + 1) % healthyTargets.length;\n    return target;\n  }\n\n  async dispatch(request) {\n    const target = this.selectTarget();\n    target.activeConnections++;\n    target.totalHandled++;\n\n    const requestId = 'req_' + crypto.randomBytes(8).toString('hex');\n    const forwardedHeaders = {\n      ...request.headers,\n      'X-Forwarded-For': request.clientIp || request.socket?.remoteAddress || 'unknown',\n      'X-Request-Id': requestId,\n      'X-Forwarded-Proto': request.protocol || 'http'\n    };\n\n    try {\n      // Simulate backend processing\n      await new Promise(r => setTimeout(r, request.latency || 10));\n      return {\n        status: 200,\n        routedTo: target.url,\n        requestId,\n        headers: forwardedHeaders\n      };\n    } finally {\n      target.activeConnections = Math.max(0, target.activeConnections - 1);\n    }\n  }\n\n  // Create HTTP server that proxies requests\n  createServer(port = 3000) {\n    const server = http.createServer(async (req, res) => {\n      try {\n        const result = await this.dispatch({\n          clientIp: req.socket.remoteAddress,\n          headers: req.headers,\n          protocol: req.socket.encrypted ? 'https' : 'http'\n        });\n        res.writeHead(result.status, result.headers);\n        res.end(JSON.stringify(result));\n      } catch (e) {\n        res.writeHead(503);\n        res.end(JSON.stringify({ error: e.message }));\n      }\n    });\n    return server;\n  }\n\n  destroy() {\n    if (this.healthCheckTimer) {\n      clearInterval(this.healthCheckTimer);\n      this.healthCheckTimer = null;\n    }\n  }\n}\n\nmodule.exports = { LoadBalancer };",
      "demo.js": "const { LoadBalancer } = require('./balancer');\n\nasync function runDemo() {\n  console.log('=== Load Balancer Demonstration ===');\n  const lb = new LoadBalancer(\n    ['http://srv-1:8080', 'http://srv-2:8080', 'http://srv-3:8080'],\n    'round-robin',\n    60000 // Disable auto health checks for demo\n  );\n\n  console.log('\\n1. Dispatch 6 requests with Round Robin:');\n  for (let i = 1; i <= 6; i++) {\n    const res = await lb.dispatch({ clientIp: '192.168.1.' + i });\n    console.log(`   Req ${i} -> ${res.routedTo} (ID: ${res.requestId})`);\n  }\n\n  console.log('\\n2. Node http://srv-2:8080 fails health check:');\n  lb.markHealth('http://srv-2:8080', false);\n\n  console.log('   Dispatch 4 more requests:');\n  for (let i = 7; i <= 10; i++) {\n    const res = await lb.dispatch({ clientIp: '192.168.1.' + i });\n    console.log(`   Req ${i} -> ${res.routedTo}`);\n  }\n\n  console.log('\\n3. Node recovers:');\n  lb.markHealth('http://srv-2:8080', true);\n  const res = await lb.dispatch({ clientIp: '192.168.1.11' });\n  console.log(`   Req 11 -> ${res.routedTo}`);\n\n  lb.destroy();\n}\n\nrunDemo();"
    }
  },
  "consistent-hashing-ring": {
    "id": "consistent-hashing-ring",
    "title": "Consistent Hashing Ring with Virtual Nodes",
    "primarySlug": "consistent-hashing",
    "summary": "A readable hash ring with virtual nodes (vnodes) and binary-search lookup, the core primitive behind cache and storage routing.",
    "files": {
      "README.md": "# Consistent Hashing Ring with Virtual Nodes\n\nConsistent hashing maps both servers and data keys onto a circular space ($[0, 2^{32}-1]$).\n\n### Why Virtual Nodes (VNodes)?\nWhen physical servers are few, hash distribution variance can leave one node holding 80% of data. By creating 100-256 virtual points per physical machine, ownership distributes evenly with minimal variance.",
      "ring.js": "const crypto = require(\"crypto\");\n\nclass ConsistentHashRing {\n  constructor(vnodes = 100) {\n    this.vnodes = vnodes;\n    this.ring = [];\n    this.nodes = new Set();\n  }\n\n  _hash(key) {\n    const md5 = crypto.createHash(\"md5\").update(String(key)).digest(\"hex\");\n    return parseInt(md5.substring(0, 8), 16);\n  }\n\n  addNode(node) {\n    this.nodes.add(node);\n    for (let i = 0; i < this.vnodes; i++) {\n      const vnodeKey = node + \"#vn\" + i;\n      const hash = this._hash(vnodeKey);\n      this.ring.push({ hash, node });\n    }\n    this.ring.sort((a, b) => a.hash - b.hash);\n  }\n\n  removeNode(node) {\n    this.nodes.delete(node);\n    this.ring = this.ring.filter(item => item.node !== node);\n  }\n\n  getNode(key) {\n    if (this.ring.length === 0) return null;\n    const hash = this._hash(key);\n\n    let low = 0;\n    let high = this.ring.length - 1;\n    let index = 0;\n\n    while (low <= high) {\n      const mid = Math.floor((low + high) / 2);\n      if (this.ring[mid].hash >= hash) {\n        index = mid;\n        high = mid - 1;\n      } else {\n        low = mid + 1;\n      }\n    }\n    return this.ring[index].node;\n  }\n}\n\nmodule.exports = { ConsistentHashRing };",
      "demo.js": "const { ConsistentHashRing } = require(\"./ring\");\n\nconst ring = new ConsistentHashRing(100);\n[\"redis-cache-1\", \"redis-cache-2\", \"redis-cache-3\"].forEach(n => ring.addNode(n));\n\nconst keys = Array.from({ length: 1000 }, (_, i) => \"user_session_\" + (i * 1337));\nconst distribution = {};\n\nkeys.forEach(k => {\n  const node = ring.getNode(k);\n  distribution[node] = (distribution[node] || 0) + 1;\n});\n\nconsole.log(\"Initial 1,000 keys distribution across 3 nodes:\");\nconsole.table(distribution);\n\nconsole.log(\"Adding 4th node: redis-cache-4...\");\nring.addNode(\"redis-cache-4\");\n\nlet migrated = 0;\nkeys.forEach(k => {\n  if (ring.getNode(k) === \"redis-cache-4\") migrated++;\n});\nconsole.log(\"Keys re-mapped to new node: \" + migrated + \" / 1000 (\" + (migrated/10).toFixed(1) + \"%, ideal ~25%)\");"
    }
  },
  "bloom-filter-membership": {
    "id": "bloom-filter-membership",
    "title": "Bloom Filter Membership Testing",
    "primarySlug": "bloom-filters",
    "summary": "A compact bit-vector membership filter that rejects non-existent keys in O(k) time with zero false negatives.",
    "files": {
      "README.md": "# Bloom Filter Membership\n\nA space-efficient probabilistic data structure.\n\n- **Guarantees**:\n  - If Bloom filter says **NO** (bit is 0): Key is **definitely NOT present** (Zero false negatives).\n  - If Bloom filter says **YES** (all bits 1): Key is **PROBABLY present** (Subject to false positive rate $\\epsilon$).",
      "bloom.js": "const crypto = require(\"crypto\");\n\nclass BloomFilter {\n  constructor(expectedItems = 10000, falsePositiveRate = 0.01) {\n    this.size = Math.ceil(- (expectedItems * Math.log(falsePositiveRate)) / (Math.LN2 ** 2));\n    this.hashCount = Math.round((this.size / expectedItems) * Math.LN2);\n    this.bits = new Uint8Array(Math.ceil(this.size / 8));\n  }\n\n  _hashes(item) {\n    const hashes = [];\n    const h1 = parseInt(crypto.createHash(\"md5\").update(item).digest(\"hex\").slice(0, 8), 16);\n    const h2 = parseInt(crypto.createHash(\"sha256\").update(item).digest(\"hex\").slice(0, 8), 16);\n    for (let i = 0; i < this.hashCount; i++) {\n      hashes.push(Math.abs((h1 + i * h2) % this.size));\n    }\n    return hashes;\n  }\n\n  add(item) {\n    for (const idx of this._hashes(item)) {\n      const byteIdx = Math.floor(idx / 8);\n      const bitOffset = idx % 8;\n      this.bits[byteIdx] |= (1 << bitOffset);\n    }\n  }\n\n  has(item) {\n    for (const idx of this._hashes(item)) {\n      const byteIdx = Math.floor(idx / 8);\n      const bitOffset = idx % 8;\n      if ((this.bits[byteIdx] & (1 << bitOffset)) === 0) {\n        return false;\n      }\n    }\n    return true;\n  }\n}\n\nmodule.exports = { BloomFilter };",
      "demo.js": "const { BloomFilter } = require(\"./bloom\");\n\nconst filter = new BloomFilter(1000, 0.01);\nconsole.log(\"Bloom Filter configured: \" + filter.size + \" bits, \" + filter.hashCount + \" hash functions\");\n\nfor (let i = 0; i < 1000; i++) filter.add(\"user_\" + i);\n\nconsole.log(\"Check existing user 'user_42':\", filter.has(\"user_42\"));\nconsole.log(\"Check non-existing user 'user_9999':\", filter.has(\"user_9999\"));\n\nlet falsePositives = 0;\nfor (let i = 10000; i < 15000; i++) {\n  if (filter.has(\"user_\" + i)) falsePositives++;\n}\nconsole.log(\"False positive test: \" + falsePositives + \"/5000 (\" + (falsePositives / 50).toFixed(2) + \"%, expected ~1%)\");"
    }
  },
    "tiny-search-engine": {
    "title": "Tiny Search Engine (Inverted Index, Compression & BM25)",
    "files": {
        "README.md": "# Building an Inverted Index Search Engine from Scratch\n\nA comprehensive engineering masterclass on constructing a full-text search engine from first principles.\n\nThis build accompanies the video tutorial [*\"Inverted Index - The Data Structure Behind Search Engines\"*](https://www.youtube.com/watch?v=iHHqnyThrqE) and the architectural breakdown [*\"BM25: The Information Retrieval Algorithm That Outlived Its Era\"*](https://arpitbhayani.me/blogs/bm25/) by Arpit Bhayani.\n\n---\n\n## 1. Architectural Overview & The Core Problem\n\nTraditional relational databases store records by Document ID (`DocID \u2192 Fields`). When evaluating a full-text search query such as:\n```sql\nSELECT * FROM documents WHERE content LIKE '%consensus%';\n```\nThe database must execute a full table scan across all `N` documents (`O(N)` execution time). At a million documents with 10 KB per document, every single search query would read 10 GB of data from disk into memory.\n\nAn **Inverted Index** reverses this layout into a term-centric dictionary:\n\n```\nForward Index:  Doc 1 \u2500\u2500\u25ba [\"raft\", \"consensus\", \"replicated\"]\n                Doc 2 \u2500\u2500\u25ba [\"consistent\", \"hashing\", \"nodes\"]\n                Doc 3 \u2500\u2500\u25ba [\"raft\", \"consensus\", \"state\"]\n\nInverted Index: \"consensus\"  \u2500\u2500\u25ba [ Doc 1, Doc 3 ]   <\u2500\u2500 Postings List (strictly sorted)\n                \"hashing\"    \u2500\u2500\u25ba [ Doc 2 ]\n                \"raft\"       \u2500\u2500\u25ba [ Doc 1, Doc 3 ]\n```\n\n```mermaid\nflowchart TD\n    subgraph IngestionPipeline [\"1. Ingestion & Index Construction\"]\n      RawDocs[\"Raw Documents (Arbitrary Corpus)\"] --> Tokenizer[\"Tokenizer & Normalizer\"]\n      Tokenizer --> Stemmer[\"Porter Suffix Stemming\"]\n      Stemmer --> Postings[\"Sorted Postings Lists (DocID + TF + Positions)\"]\n      Postings --> DeltaComp[\"Delta + Variable Byte Compression\"]\n      Postings --> ChampBuild[\"Tier 1 Champion Lists (Top-K PageRank)\"]\n    end\n\n    subgraph QueryPipeline [\"2. Online Query Serving\"]\n      UserQuery[\"User Query: 'distributed consensus'\"] --> QTok[\"Query Tokenizer\"]\n      QTok --> QueryPlan{\"Matches in Tier 1?\"}\n      QueryPlan -->|\"Yes (sub-5ms)\"| Ranker[\"Okapi BM25 Ranking Formula\"]\n      QueryPlan -->|\"No\"| Cascade[\"Cascade to Tier 2 Full Archive\"]\n      Cascade --> Ranker\n      Ranker --> TopResults[\"Top-K Scored Results\"]\n    end\n```\n\n---\n\n## 2. The Document Ingestion Pipeline\n\nText cannot be indexed directly. If Document 1 contains `\"Consensus!\"` and Document 2 contains `\"consensus,\"`, a naive equality check fails. Raw text must pass through three normalization stages:\n\n### Step 2.1: Case Folding & Punctuation Stripping\nInput text is converted to lowercase and non-alphanumeric characters are stripped. Whitespace is collapsed into single delimiter spaces:\n```javascript\nconst cleaned = text.toLowerCase().replace(/[^a-z0-9\\s]/g, ' ').trim();\n```\n\n### Step 2.2: Stop-Word Elimination\nUbiquitous grammatical words (`the`, `is`, `at`, `and`, `to`) appear in almost every document. They carry near-zero information entropy while inflating index memory.\n\n> [!NOTE]\n> Early search engines aggressively stripped all stop words. Modern search engines retain stop words for phrase and positional lookups (e.g. *\"To be or not to be\"* or the band *\"The Who\"*), but assign them near-zero weight using inverse document frequency (IDF).\n\n### Step 2.3: Algorithmic Suffix Stemming\nUsers searching for `\"searched\"` or `\"searching\"` expect documents containing `\"search\"` to match. We apply a Porter-style morphological suffix reduction:\n- `ies` \u2192 `y` (e.g. `cities` \u2192 `city`)\n- `sses` \u2192 `ss` (e.g. `dresses` \u2192 `dress`)\n- `ing` \u2192 root (e.g. `running` \u2192 `runn`)\n- `ed` \u2192 root (e.g. `searched` \u2192 `search`)\n- `es` \u2192 root (e.g. `searches` \u2192 `search`)\n- `s` \u2192 root (e.g. `dogs` \u2192 `dog`)\n\n---\n\n## 3. The Anatomy of a Production Postings List\n\nIn production engines (Apache Lucene, Elasticsearch), a postings list is not merely an array of integers. Each entry records:\n1. **Document ID (`DocID`):** Strictly sorted in ascending order (`[1, 4, 12, 99]`).\n2. **Term Frequency (`tf`):** The number of times the term appears within the document (used for BM25 ranking).\n3. **Word Positions (`positions`):** The token offsets where the term occurred (used for exact phrase searches and snippet highlighting).\n4. **Skip Pointers:** Pointers that leap forward past blocks of IDs (e.g. every 8 or 128 documents) to avoid linear scanning during intersections.\n\n---\n\n## 4. Set Intersection Algorithms (`O(N + M)`)\n\nThe strict ascending sorting invariant of document IDs enables two-pointer linear merge operations:\n\n### Conjunction (Boolean AND)\nTwo cursors advance concurrently across sorted lists `A` and `B`:\n- If `DocID_A == DocID_B`, record match and advance both cursors.\n- If `DocID_A < DocID_B`, advance cursor `A`.\n- If `DocID_A > DocID_B`, advance cursor `B`.\n\nComplexity: **`O(N + M)`**, compared to `O(N \u00d7 M)` in unindexed databases.\n\n### The Rarest-First Heuristic\nWhen evaluating multi-term queries (`distributed AND consensus AND raft`), we sort postings lists by length ascending (`df`) first. Intersecting the smallest list first dramatically shrinks intermediate candidate sets, slashing memory and CPU comparisons.\n\n### Positional Exact Phrase Search\nTo evaluate exact phrase queries (`\"distributed consensus\"`):\n1. Intersect document IDs to find documents containing both terms.\n2. For matching documents, verify that a position of the second term immediately follows the first (`pos_B = pos_A + 1`).\n\n---\n\n## 5. Postings List Compression Engineering\n\nStoring raw 32-bit integers for millions of document IDs consumes gigabytes of memory and swamps memory bandwidth:\n\n### 1. Delta (Gap) Encoding\nBecause postings lists are strictly sorted, we replace absolute IDs (`[1000, 1004, 1008, 1020]`) with the differences between consecutive IDs (`[1000, 4, 4, 12]`). All deltas become small positive numbers.\n\n### 2. Variable-Byte (VByte / VarInt) Compression\nStandard 32-bit integers consume 4 bytes regardless of value. VByte encodes numbers into 7 bits per byte, reserving the 8th bit (MSB) as a continuation/termination flag:\n- Values `< 128` consume only **1 byte** (a 75% immediate reduction).\n- Values `< 16,384` consume **2 bytes** (a 50% reduction).\n\n> [!TIP]\n> Apache Lucene uses **Frame of Reference (FoR)** bit-packing for blocks of 128 integers, calculating the maximum bit-width required in each block to pack integers with zero wasted bits.\n\n---\n\n## 6. Scale & Tiered Architecture: Champion Lists\n\nWhen serving millions of users, querying the full multi-gigabyte postings archive on every keystroke exhausts disk I/O.\n\nSearch engines partition documents into quality tiers:\n- **Tier 1 (Hot In-Memory Core):** Maintains precomputed \"Champion Lists\" in RAM containing the top-`K` highest-authority documents per term (ranked by PageRank, click velocity, or document quality).\n- **Tier 2 (Cold Disk Archive):** Stores complete postings lists on NVMe SSDs or persistent storage.\n\n**Query Routing:** Queries first evaluate against Tier 1. If Tier 1 returns `\u2265 K` results (the common case for 90%+ of queries), the engine returns immediately with single-digit millisecond latency. Only when matches are insufficient does it cascade to Tier 2.\n\n---\n\n## 7. Relevance Ranking: Okapi BM25 Deep Dive\n\nWhile TF-IDF laid the foundation for information retrieval, raw TF grows linearly: a document mentioning a keyword 500 times scores 50x higher than one mentioning it 10 times, making it vulnerable to keyword stuffing.\n\n**Okapi BM25** (Best Matching 25) solves this with non-linear saturation:\n\n```\nBM25(D, Q) = \u03a3 IDF(q\u1d62) \u00d7 [ (f(q\u1d62, D) \u00d7 (k\u2081 + 1)) / (f(q\u1d62, D) + k\u2081 \u00d7 (1 - b + b \u00d7 (|D| / avgdl))) ]\n```\n\n### Key Parameters:\n1. **Term Saturation Parameter `k\u2081` (Default: \u2248 1.2):** Controls how quickly the term frequency score saturates. As keyword occurrences increase, incremental score gains diminish, asymptotically approaching a ceiling of `k\u2081 + 1`.\n2. **Document Length Normalization `b` (Default: \u2248 0.75):** Penalizes long, verbose documents relative to the average corpus length (`avgdl`). When `b = 1.0`, scores are fully scaled by document length; when `b = 0`, length normalization is disabled.\n3. **Robertson-Sp\u00e4rck Jones IDF with Lucene Smoothing:**\n```\nIDF(q) = ln( 1 + (N - df + 0.5) / (df + 0.5) )\n```\nAdding `1` inside the logarithm guarantees that IDF never goes negative, even for high-frequency terms.\n\n---\n\n## 8. Scalability: Indexing Any Volume of Data\n\nThe engine provides both single-document (`addDocument`) and bulk-ingestion (`addDocuments`) APIs. It handles arbitrary document counts:\n\n```javascript\nconst engine = new InvertedIndexEngine({ k1: 1.2, b: 0.75, championK: 10 });\n\n// Ingest any volume of records dynamically\nengine.addDocuments([\n  { id: 1, text: \"Distributed systems consensus protocols...\", staticScore: 0.95 },\n  { id: 2, text: \"Consistent hashing in distributed caches...\", staticScore: 0.88 },\n  // ... any number of documents (10, 1,000, 100,000+)\n]);\n\n// Build Tier-1 hot in-memory index\nengine.buildChampionLists();\n\n// Execute exact phrase search\nconst phrases = engine.searchPhrase(\"distributed systems\");\n\n// Execute Okapi BM25 ranked search\nconst ranked = engine.searchBM25(\"consensus protocols\", { topK: 5 });\n```\n\n---\n\n## 9. Verification & Running the Lab\n\nRun the interactive demonstration script:\n```bash\nnode projects/tiny-search-engine/src/demo.js\n```\n\nRun the automated test suite:\n```bash\nnode projects/tiny-search-engine/src/test.js\n```",
        "engine.js": "/**\n * Inverted Index Search Engine \u2014 Complete Self-Contained Implementation\n * \n * Features:\n * 1. Tokenizer with punctuation stripping, case folding, stop words, and Porter suffix stemming\n * 2. Positional indexing: records token offsets for exact phrase search\n * 3. Postings List: strictly sorted doc IDs with skip pointers for sublinear traversal\n * 4. Compression: Delta (gap) encoding + Variable-Byte (VByte) 7-bit continuation compression\n * 5. Set operations: Two-pointer linear merge for AND, OR, AND NOT, and phrase adjacency\n * 6. Tiered storage: Champion lists (Tier 1 hot in-memory) + complete archive (Tier 2)\n * 7. Relevance ranking: Okapi BM25 with length normalization and static PageRank boost\n * 8. Scalable ingestion: addDocument and addDocuments for arbitrary dataset volumes\n */\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// 1. Text Normalization & Porter Stemmer\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nconst DEFAULT_STOP_WORDS = new Set([\n  'a', 'about', 'above', 'after', 'again', 'against', 'all', 'am', 'an', 'and', 'any', 'are',\n  'as', 'at', 'be', 'because', 'been', 'before', 'being', 'below', 'between', 'both', 'but',\n  'by', 'could', 'did', 'do', 'does', 'doing', 'down', 'during', 'each', 'few', 'for', 'from',\n  'further', 'had', 'has', 'have', 'having', 'he', 'her', 'here', 'hers', 'herself', 'him',\n  'himself', 'his', 'how', 'i', 'if', 'in', 'into', 'is', 'it', 'its', 'itself', 'just', 'me',\n  'more', 'most', 'my', 'myself', 'no', 'nor', 'not', 'of', 'off', 'on', 'once', 'only', 'or',\n  'other', 'ought', 'our', 'ours', 'ourselves', 'out', 'over', 'own', 'same', 'she', 'should',\n  'so', 'some', 'such', 'than', 'that', 'the', 'their', 'theirs', 'them', 'themselves', 'then',\n  'there', 'these', 'they', 'this', 'those', 'through', 'to', 'too', 'under', 'until', 'up',\n  'very', 'was', 'we', 'were', 'what', 'when', 'where', 'which', 'while', 'who', 'whom', 'why',\n  'with', 'would', 'you', 'your', 'yours', 'yourself', 'yourselves'\n]);\n\nfunction stemWord(word) {\n  if (word.length <= 3) return word;\n  let w = word;\n  if (w.endsWith('ies') && w.length > 4) return w.slice(0, -3) + 'y';\n  if (w.endsWith('sses')) return w.slice(0, -2);\n  if (w.endsWith('tions') || w.endsWith('tion')) return w.replace(/tions?$/, 't');\n  if (w.endsWith('ments') || w.endsWith('ment')) return w.replace(/ments?$/, '');\n  if (w.endsWith('ing') && w.length > 5) return w.slice(0, -3);\n  if (w.endsWith('ed') && w.length > 4) return w.slice(0, -2);\n  if (w.endsWith('ly') && w.length > 4) return w.slice(0, -2);\n  if (w.endsWith('es') && w.length > 4) return w.slice(0, -2);\n  if (w.endsWith('s') && !w.endsWith('ss') && w.length > 3) return w.slice(0, -1);\n  return w;\n}\n\nfunction tokenize(text, options = {}) {\n  const {\n    removeStopWords = true,\n    stem = true,\n    withPositions = false,\n    customStopWords = DEFAULT_STOP_WORDS\n  } = options;\n\n  if (!text || typeof text !== 'string') return [];\n\n  const cleaned = text.toLowerCase().replace(/[^a-z0-9\\s]/g, ' ').trim();\n  if (!cleaned) return [];\n\n  const rawTokens = cleaned.split(/\\s+/).filter(Boolean);\n  const tokens = [];\n\n  for (let pos = 0; pos < rawTokens.length; pos++) {\n    const raw = rawTokens[pos];\n    if (removeStopWords && customStopWords.has(raw)) continue;\n    const finalToken = stem ? stemWord(raw) : raw;\n    if (finalToken.length > 0) {\n      if (withPositions) {\n        tokens.push({ term: finalToken, position: pos });\n      } else {\n        tokens.push(finalToken);\n      }\n    }\n  }\n\n  return tokens;\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// 2. Delta & Variable-Byte (VByte) Compression\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nfunction deltaEncode(sortedArray) {\n  if (!sortedArray || sortedArray.length === 0) return [];\n  const deltas = [sortedArray[0]];\n  for (let i = 1; i < sortedArray.length; i++) {\n    deltas.push(sortedArray[i] - sortedArray[i - 1]);\n  }\n  return deltas;\n}\n\nfunction deltaDecode(deltas) {\n  if (!deltas || deltas.length === 0) return [];\n  const result = [deltas[0]];\n  for (let i = 1; i < deltas.length; i++) {\n    result.push(result[i - 1] + deltas[i]);\n  }\n  return result;\n}\n\nfunction vbyteEncode(numbers) {\n  const bytes = [];\n  for (let num of numbers) {\n    if (num < 0) throw new Error('VByte only supports non-negative integers');\n    const numBytes = [];\n    numBytes.push((num & 0x7f) | 0x80);\n    num = Math.floor(num / 128);\n    while (num > 0) {\n      numBytes.push(num & 0x7f);\n      num = Math.floor(num / 128);\n    }\n    for (let i = numBytes.length - 1; i >= 0; i--) {\n      bytes.push(numBytes[i]);\n    }\n  }\n  return Buffer.from(bytes);\n}\n\nfunction vbyteDecode(buffer) {\n  const numbers = [];\n  let currentNum = 0;\n  for (let i = 0; i < buffer.length; i++) {\n    const b = buffer[i];\n    if ((b & 0x80) === 0) {\n      currentNum = currentNum * 128 + b;\n    } else {\n      currentNum = currentNum * 128 + (b & 0x7f);\n      numbers.push(currentNum);\n      currentNum = 0;\n    }\n  }\n  return numbers;\n}\n\nfunction benchmarkCompression(sortedDocIds) {\n  const rawBytes = sortedDocIds.length * 4;\n  const deltas = deltaEncode(sortedDocIds);\n  const compressedBuffer = vbyteEncode(deltas);\n  const compressedBytes = compressedBuffer.length;\n  const ratio = ((1 - (compressedBytes / rawBytes)) * 100).toFixed(1);\n  return { rawBytes, compressedBytes, savingsPercent: ratio + '%' };\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// 3. Postings List & Two-Pointer Operations\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nclass PostingList {\n  constructor(term = '', skipInterval = 8) {\n    this.term = term;\n    this.entries = []; // Array of { docId, tf, positions: [] }\n    this.skipInterval = skipInterval;\n    this.skipPointers = [];\n  }\n\n  get length() {\n    return this.entries.length;\n  }\n\n  add(docId, tf = 1, positions = []) {\n    const posArr = Array.isArray(positions) ? [...positions] : [];\n    const entry = { docId, tf, positions: posArr };\n\n    if (this.entries.length === 0 || docId > this.entries[this.entries.length - 1].docId) {\n      this.entries.push(entry);\n    } else {\n      let low = 0;\n      let high = this.entries.length;\n      while (low < high) {\n        const mid = (low + high) >>> 1;\n        if (this.entries[mid].docId === docId) {\n          this.entries[mid].tf += tf;\n          if (posArr.length > 0) {\n            this.entries[mid].positions = (this.entries[mid].positions || []).concat(posArr);\n            this.entries[mid].positions.sort((a, b) => a - b);\n          }\n          return;\n        }\n        if (this.entries[mid].docId < docId) low = mid + 1;\n        else high = mid;\n      }\n      this.entries.splice(low, 0, entry);\n    }\n    this._updateSkipPointers();\n  }\n\n  _updateSkipPointers() {\n    this.skipPointers = [];\n    for (let i = 0; i < this.entries.length; i += this.skipInterval) {\n      this.skipPointers.push({ index: i, docId: this.entries[i].docId });\n    }\n  }\n\n  getDocIds() {\n    return this.entries.map(e => e.docId);\n  }\n\n  skipForward(currentIndex, targetDocId) {\n    if (this.skipPointers.length === 0) return currentIndex;\n    let bestSkipIdx = currentIndex;\n    for (const skip of this.skipPointers) {\n      if (skip.index > currentIndex && skip.docId <= targetDocId) bestSkipIdx = skip.index;\n      else if (skip.docId > targetDocId) break;\n    }\n    return bestSkipIdx;\n  }\n}\n\nfunction intersectPostings(listA, listB) {\n  const result = [];\n  const entriesA = listA instanceof PostingList ? listA.entries : (Array.isArray(listA) ? listA : []);\n  const entriesB = listB instanceof PostingList ? listB.entries : (Array.isArray(listB) ? listB : []);\n  let pA = 0, pB = 0;\n\n  while (pA < entriesA.length && pB < entriesB.length) {\n    const docA = entriesA[pA].docId !== undefined ? entriesA[pA].docId : entriesA[pA];\n    const docB = entriesB[pB].docId !== undefined ? entriesB[pB].docId : entriesB[pB];\n\n    if (docA === docB) {\n      result.push({ docId: docA, tfA: entriesA[pA].tf || 1, tfB: entriesB[pB].tf || 1 });\n      pA++;\n      pB++;\n    } else if (docA < docB) {\n      if (listA && listA.skipForward) {\n        const next = listA.skipForward(pA, docB);\n        pA = next > pA ? next : pA + 1;\n      } else {\n        pA++;\n      }\n    } else {\n      if (listB && listB.skipForward) {\n        const next = listB.skipForward(pB, docA);\n        pB = next > pB ? next : pB + 1;\n      } else {\n        pB++;\n      }\n    }\n  }\n  return result;\n}\n\nfunction intersectAll(lists) {\n  if (!lists || lists.length === 0) return [];\n  if (lists.length === 1) return lists[0] instanceof PostingList ? lists[0].entries : lists[0];\n\n  const sorted = [...lists].sort((a, b) => {\n    const lenA = a instanceof PostingList ? a.length : a.length;\n    const lenB = b instanceof PostingList ? b.length : b.length;\n    return lenA - lenB;\n  });\n\n  let current = sorted[0] instanceof PostingList ? sorted[0].entries : sorted[0];\n  for (let i = 1; i < sorted.length; i++) {\n    if (current.length === 0) break;\n    current = intersectPostings(current, sorted[i]);\n  }\n  return current;\n}\n\nfunction unionPostings(listA, listB) {\n  const result = [];\n  const entriesA = listA instanceof PostingList ? listA.entries : (Array.isArray(listA) ? listA : []);\n  const entriesB = listB instanceof PostingList ? listB.entries : (Array.isArray(listB) ? listB : []);\n  let pA = 0, pB = 0;\n\n  while (pA < entriesA.length && pB < entriesB.length) {\n    const docA = entriesA[pA].docId !== undefined ? entriesA[pA].docId : entriesA[pA];\n    const docB = entriesB[pB].docId !== undefined ? entriesB[pB].docId : entriesB[pB];\n\n    if (docA === docB) {\n      result.push({ docId: docA, tf: (entriesA[pA].tf || 1) + (entriesB[pB].tf || 1) });\n      pA++;\n      pB++;\n    } else if (docA < docB) {\n      result.push({ docId: docA, tf: entriesA[pA].tf || 1 });\n      pA++;\n    } else {\n      result.push({ docId: docB, tf: entriesB[pB].tf || 1 });\n      pB++;\n    }\n  }\n\n  while (pA < entriesA.length) {\n    result.push({ docId: entriesA[pA].docId !== undefined ? entriesA[pA].docId : entriesA[pA], tf: entriesA[pA].tf || 1 });\n    pA++;\n  }\n  while (pB < entriesB.length) {\n    result.push({ docId: entriesB[pB].docId !== undefined ? entriesB[pB].docId : entriesB[pB], tf: entriesB[pB].tf || 1 });\n    pB++;\n  }\n  return result;\n}\n\nfunction differencePostings(listA, listB) {\n  const result = [];\n  const entriesA = listA instanceof PostingList ? listA.entries : (Array.isArray(listA) ? listA : []);\n  const entriesB = listB instanceof PostingList ? listB.entries : (Array.isArray(listB) ? listB : []);\n  let pA = 0, pB = 0;\n\n  while (pA < entriesA.length && pB < entriesB.length) {\n    const docA = entriesA[pA].docId !== undefined ? entriesA[pA].docId : entriesA[pA];\n    const docB = entriesB[pB].docId !== undefined ? entriesB[pB].docId : entriesB[pB];\n\n    if (docA === docB) {\n      pA++;\n      pB++;\n    } else if (docA < docB) {\n      result.push({ docId: docA, tf: entriesA[pA].tf || 1 });\n      pA++;\n    } else {\n      pB++;\n    }\n  }\n\n  while (pA < entriesA.length) {\n    result.push({ docId: entriesA[pA].docId !== undefined ? entriesA[pA].docId : entriesA[pA], tf: entriesA[pA].tf || 1 });\n    pA++;\n  }\n  return result;\n}\n\nfunction intersectPhrase(listA, listB) {\n  const result = [];\n  const entriesA = listA instanceof PostingList ? listA.entries : (Array.isArray(listA) ? listA : []);\n  const entriesB = listB instanceof PostingList ? listB.entries : (Array.isArray(listB) ? listB : []);\n  let i = 0, j = 0;\n\n  while (i < entriesA.length && j < entriesB.length) {\n    if (entriesA[i].docId === entriesB[j].docId) {\n      const docId = entriesA[i].docId;\n      const posA = entriesA[i].positions || [];\n      const posB = entriesB[j].positions || [];\n      const matchedPositions = [];\n      let pA = 0, pB = 0;\n\n      while (pA < posA.length && pB < posB.length) {\n        if (posB[pB] === posA[pA] + 1) {\n          matchedPositions.push(posB[pB]);\n          pA++;\n          pB++;\n        } else if (posB[pB] < posA[pA] + 1) {\n          pB++;\n        } else {\n          pA++;\n        }\n      }\n\n      if (matchedPositions.length > 0) {\n        result.push({ docId, tf: matchedPositions.length, positions: matchedPositions });\n      }\n      i++;\n      j++;\n    } else if (entriesA[i].docId < entriesB[j].docId) {\n      i++;\n    } else {\n      j++;\n    }\n  }\n  return result;\n}\n\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n// 4. Inverted Index Engine & Relevance Ranking\n// \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nclass InvertedIndexEngine {\n  constructor(options = {}) {\n    const { k1 = 1.2, b = 0.75, championK = 5 } = options;\n    this.k1 = k1;\n    this.b = b;\n    this.championK = championK;\n    this.documents = new Map();     // docId -> { text, staticScore, length }\n    this.totalDocLength = 0;\n    this.index = new Map();         // term -> PostingList\n    this.championIndex = new Map(); // term -> PostingList (Tier 1 Top-K)\n  }\n\n  get docCount() {\n    return this.documents.size;\n  }\n\n  get avgDocLength() {\n    return this.docCount > 0 ? this.totalDocLength / this.docCount : 0;\n  }\n\n  addDocument(id, text, staticScore = 0.5) {\n    if (this.documents.has(id)) {\n      throw new Error(`Document with ID ${id} already indexed.`);\n    }\n\n    const tokenObjects = tokenize(text, { withPositions: true });\n    const docLength = tokenObjects.length;\n\n    this.documents.set(id, { text, staticScore, length: docLength });\n    this.totalDocLength += docLength;\n\n    const termMap = new Map();\n    for (const { term, position } of tokenObjects) {\n      if (!termMap.has(term)) termMap.set(term, { tf: 0, positions: [] });\n      const entry = termMap.get(term);\n      entry.tf += 1;\n      entry.positions.push(position);\n    }\n\n    for (const [term, { tf, positions }] of termMap.entries()) {\n      if (!this.index.has(term)) this.index.set(term, new PostingList(term));\n      this.index.get(term).add(id, tf, positions);\n    }\n  }\n\n  addDocuments(docs) {\n    if (!Array.isArray(docs)) throw new TypeError('addDocuments expects an array of document objects: [{ id, text, staticScore? }]');\n    for (const doc of docs) {\n      if (doc && doc.id !== undefined && doc.text !== undefined) {\n        this.addDocument(doc.id, doc.text, doc.staticScore ?? 0.5);\n      }\n    }\n  }\n\n  buildChampionLists() {\n    this.championIndex.clear();\n    for (const [term, postingList] of this.index.entries()) {\n      const sortedEntries = [...postingList.entries].sort((a, b) => {\n        const scoreA = (this.documents.get(a.docId)?.staticScore || 0) + (a.tf * 0.1);\n        const scoreB = (this.documents.get(b.docId)?.staticScore || 0) + (b.tf * 0.1);\n        return scoreB - scoreA;\n      });\n\n      const topK = sortedEntries.slice(0, this.championK);\n      const champList = new PostingList(term);\n      for (const entry of topK) {\n        champList.add(entry.docId, entry.tf, entry.positions);\n      }\n      this.championIndex.set(term, champList);\n    }\n  }\n\n  scoreBM25(docId, queryTerms, postingMap = this.index) {\n    const docMeta = this.documents.get(docId);\n    if (!docMeta) return 0;\n\n    const N = this.docCount;\n    const avgdl = this.avgDocLength;\n    const docLen = docMeta.length;\n    let totalScore = 0;\n\n    for (const term of queryTerms) {\n      const plist = postingMap.get(term);\n      if (!plist) continue;\n\n      const df = plist.length;\n      const idf = Math.log(1 + ((N - df + 0.5) / (df + 0.5)));\n\n      const match = plist.entries.find(e => e.docId === docId);\n      if (!match) continue;\n\n      const tf = match.tf;\n      const numerator = tf * (this.k1 + 1);\n      const denominator = tf + this.k1 * (1 - this.b + this.b * (docLen / (avgdl || 1)));\n      totalScore += idf * (numerator / denominator);\n    }\n\n    const staticBoost = (docMeta.staticScore || 0) * 0.5;\n    return totalScore + staticBoost;\n  }\n\n  searchBoolean(query, useChampion = false) {\n    const { must = [], should = [], mustNot = [] } = typeof query === 'string' ? { must: query.split(/\\s+/) } : query;\n    const pMap = useChampion ? this.championIndex : this.index;\n    let candidatePostings = null;\n\n    if (must.length > 0) {\n      const mustLists = [];\n      for (const rawTerm of must) {\n        const [term] = tokenize(rawTerm);\n        if (!term) continue;\n        const list = pMap.get(term);\n        if (!list || list.length === 0) return [];\n        mustLists.push(list);\n      }\n      candidatePostings = intersectAll(mustLists);\n    }\n\n    if (should.length > 0) {\n      const shouldLists = [];\n      for (const rawTerm of should) {\n        const [term] = tokenize(rawTerm);\n        if (!term) continue;\n        const list = pMap.get(term);\n        if (list) shouldLists.push(list);\n      }\n\n      if (shouldLists.length > 0) {\n        let unionRes = shouldLists[0].entries;\n        for (let i = 1; i < shouldLists.length; i++) {\n          unionRes = unionPostings(unionRes, shouldLists[i].entries);\n        }\n        candidatePostings = candidatePostings === null ? unionRes : intersectPostings(candidatePostings, unionRes);\n      }\n    }\n\n    if (!candidatePostings) return [];\n\n    if (mustNot.length > 0) {\n      for (const rawTerm of mustNot) {\n        const [term] = tokenize(rawTerm);\n        if (!term) continue;\n        const notList = pMap.get(term);\n        if (notList) {\n          candidatePostings = differencePostings(candidatePostings, notList.entries);\n        }\n      }\n    }\n\n    return candidatePostings.map(e => e.docId);\n  }\n\n  searchPhrase(phrase) {\n    const queryTokens = tokenize(phrase, { removeStopWords: false });\n    if (queryTokens.length === 0) return [];\n\n    if (queryTokens.length === 1) {\n      const list = this.index.get(queryTokens[0]);\n      if (!list) return [];\n      return list.entries.map(e => ({ docId: e.docId, tf: e.tf, text: this.documents.get(e.docId)?.text }));\n    }\n\n    let candidates = this.index.get(queryTokens[0])?.entries;\n    if (!candidates || candidates.length === 0) return [];\n\n    for (let i = 1; i < queryTokens.length; i++) {\n      const nextList = this.index.get(queryTokens[i])?.entries;\n      if (!nextList || nextList.length === 0) return [];\n      candidates = intersectPhrase(candidates, nextList);\n      if (candidates.length === 0) break;\n    }\n\n    return candidates.map(c => ({ docId: c.docId, matchCount: c.tf, text: this.documents.get(c.docId)?.text }));\n  }\n\n  searchBM25(query, options = {}) {\n    const { topK = 5, useChampionLists = true } = options;\n    const queryTokens = tokenize(query);\n    if (queryTokens.length === 0) return { results: [], tierUsed: 'none' };\n\n    let candidateDocIds = [];\n    let tierUsed = 'Tier-2 (Archive)';\n\n    if (useChampionLists && this.championIndex.size > 0) {\n      const champLists = queryTokens.map(t => this.championIndex.get(t)).filter(Boolean);\n      if (champLists.length === queryTokens.length) {\n        const matches = intersectAll(champLists);\n        if (matches.length >= topK) {\n          candidateDocIds = matches.map(m => m.docId);\n          tierUsed = 'Tier-1 (Champion In-Memory Fast Path)';\n        }\n      }\n    }\n\n    if (candidateDocIds.length < topK) {\n      tierUsed = 'Tier-2 (Full Inverted Index Archive)';\n      const docSet = new Set();\n      for (const term of queryTokens) {\n        const plist = this.index.get(term);\n        if (plist) {\n          for (const entry of plist.entries) docSet.add(entry.docId);\n        }\n      }\n      candidateDocIds = Array.from(docSet);\n    }\n\n    const scoredResults = candidateDocIds.map(docId => {\n      const score = this.scoreBM25(docId, queryTokens, this.index);\n      const doc = this.documents.get(docId);\n      return {\n        docId,\n        score: Number(score.toFixed(4)),\n        staticScore: doc.staticScore,\n        text: doc.text\n      };\n    });\n\n    scoredResults.sort((a, b) => b.score - a.score);\n\n    return {\n      query,\n      tokens: queryTokens,\n      tierUsed,\n      totalCandidates: candidateDocIds.length,\n      results: scoredResults.slice(0, topK)\n    };\n  }\n\n  search(query, options = {}) {\n    return this.searchBM25(query, options);\n  }\n}\n\nmodule.exports = {\n  tokenize,\n  stemWord,\n  deltaEncode,\n  deltaDecode,\n  vbyteEncode,\n  vbyteDecode,\n  benchmarkCompression,\n  PostingList,\n  intersectPostings,\n  intersectAll,\n  unionPostings,\n  differencePostings,\n  intersectPhrase,\n  InvertedIndexEngine,\n  DEFAULT_STOP_WORDS\n};",
        "demo.js": "/**\n * Inverted Index Search Engine \u2014 Interactive Hands-on Lab\n * \n * Based on principles from \"Inverted Index - The Data Structure Behind Search Engines\"\n * and production Information Retrieval architecture (Apache Lucene, Elasticsearch).\n */\n\nconst { InvertedIndexEngine } = require('./engine');\nconst { tokenize } = require('./tokenizer');\nconst { benchmarkCompression, deltaEncode, vbyteEncode } = require('./compression');\n\nfunction printSection(title) {\n  console.log('\\n' + '='.repeat(70));\n  console.log(`  ${title}`);\n  console.log('='.repeat(70));\n}\n\nasync function runLab() {\n  console.log('\\n\ud83d\udd0d WELCOME TO THE FROM-SCRATCH INVERTED INDEX LAB');\n  console.log('   An architectural walkthrough of how modern search engines operate.');\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 1. Ingestion & Tokenization\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 1: Ingesting Corpus & Text Normalization');\n\n  const corpus = [\n    {\n      id: 1,\n      text: 'Distributed consensus algorithms like Raft and Paxos ensure consistency across replicas.',\n      pagerank: 0.95\n    },\n    {\n      id: 2,\n      text: 'Consistent hashing with virtual nodes ensures minimal data movement during scaling.',\n      pagerank: 0.88\n    },\n    {\n      id: 3,\n      text: 'Raft is an understandable consensus algorithm for replicated state machines in distributed systems.',\n      pagerank: 0.91\n    },\n    {\n      id: 4,\n      text: 'Apache Lucene builds an inverted index using immutable segment files and postings lists.',\n      pagerank: 0.97\n    },\n    {\n      id: 5,\n      text: 'Elasticsearch scales inverted index queries using primary and replica shards across nodes.',\n      pagerank: 0.93\n    },\n    {\n      id: 6,\n      text: 'Postings lists store sorted document IDs, compressed using delta gaps and variable byte encoding.',\n      pagerank: 0.92\n    },\n    {\n      id: 7,\n      text: 'Bloom filters provide space-efficient membership testing to avoid unnecessary disk lookups.',\n      pagerank: 0.80\n    },\n    {\n      id: 8,\n      text: 'Write-ahead logs record state changes sequentially before committing transactions to memory.',\n      pagerank: 0.85\n    }\n  ];\n\n  const engine = new InvertedIndexEngine({ championK: 2 });\n\n  for (const doc of corpus) {\n    engine.addDocument(doc.id, doc.text, doc.pagerank);\n  }\n  engine.buildChampionLists();\n\n  console.log(`Indexed ${corpus.length} documents. Total terms processed: ${engine.totalDocLength}`);\n  console.log(`Average document length: ${engine.avgDocLength.toFixed(2)} tokens.\\n`);\n\n  console.log('Sample Tokenization Trace:');\n  const sample = 'Distributed Systems & Scaling: What is an Inverted Index?';\n  console.log(`  Original:   \"${sample}\"`);\n  console.log(`  Tokenized:  [ ${tokenize(sample).map(t => `'${t}'`).join(', ')} ]`);\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 2. Term Dictionary & Postings Lists\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 2: Inverted Term Dictionary & Postings Lists');\n  console.log('Term -> Postings List (DocID : TF):');\n\n  const sampleTerms = ['consensu', 'raft', 'index', 'post', 'distribut', 'compress'];\n  for (const term of sampleTerms) {\n    const plist = engine.index.get(term);\n    if (plist) {\n      const formatted = plist.entries.map(e => `Doc ${e.docId}(tf=${e.tf})`).join(' -> ');\n      console.log(`  '${term.padEnd(12)}' -> [ ${formatted} ] (DF = ${plist.length})`);\n    }\n  }\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 3. Postings List Compression Lab (Delta + VByte)\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 3: Postings Compression (Delta Gaps + Variable Byte)');\n  console.log('Why keep Document IDs sorted? To enable Delta Encoding!\\n');\n\n  // Simulate a realistic web postings list with 20 sorted document IDs\n  const samplePostings = [\n    1002, 1005, 1009, 1014, 1025, 1050, 1052, 1060, 1095, 1120,\n    1155, 1200, 1204, 1209, 1250, 1300, 1315, 1340, 1380, 1420\n  ];\n\n  const deltas = deltaEncode(samplePostings);\n  const bench = benchmarkCompression(samplePostings);\n\n  console.log('1. Raw Document IDs (Sorted):');\n  console.log('   ', samplePostings.slice(0, 10).join(', ') + ' ...');\n  console.log('\\n2. After Delta / Gap Encoding (differences between consecutive IDs):');\n  console.log('   ', deltas.slice(0, 10).join(', ') + ' ...');\n  console.log('\\n3. Memory & Disk Space Analysis:');\n  console.log(`   - Raw 32-bit Integer Storage: ${bench.rawBytes} bytes (${samplePostings.length} \u00d7 4 bytes)`);\n  console.log(`   - Delta + VByte Compressed:   ${bench.compressedBytes} bytes`);\n  console.log(`   - Space Reduction / Savings:  ${bench.savingsPercent} \ud83c\udf89`);\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 4. Two-Pointer Boolean Query Evaluation\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 4: Two-Pointer Boolean Query Evaluation (O(N + M))');\n\n  console.log('A. Boolean AND: \"consensus AND raft\"');\n  const boolAnd = engine.searchBoolean({ must: ['consensus', 'raft'] });\n  console.log(`   Matches (must contain both): Document IDs [ ${boolAnd.join(', ')} ]`);\n\n  console.log('\\nB. Boolean OR: \"paxos OR hashing\"');\n  const boolOr = engine.searchBoolean({ should: ['paxos', 'hashing'] });\n  console.log(`   Matches (contains either):   Document IDs [ ${boolOr.join(', ')} ]`);\n\n  console.log('\\nC. Boolean NOT: \"consensus AND NOT paxos\"');\n  const boolNot = engine.searchBoolean({ must: ['consensus'], mustNot: ['paxos'] });\n  console.log(`   Matches (contains consensus without paxos): Document IDs [ ${boolNot.join(', ')} ]`);\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 5. Positional Exact Phrase Search (Proximity & Offsets)\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 5: Positional Exact Phrase Search');\n  console.log('Postings lists store word positions to enable exact phrase queries without false positives.\\n');\n\n  const phrase1 = 'distributed consensus';\n  const phraseHits1 = engine.searchPhrase(phrase1);\n  console.log(`Query Phrase: \"${phrase1}\"`);\n  console.log(`Matching Documents: ${phraseHits1.length} found`);\n  phraseHits1.forEach(h => console.log(`  -> Doc ${h.docId}: \"${h.text}\"`));\n\n  const phrase2 = 'replicated state machines';\n  const phraseHits2 = engine.searchPhrase(phrase2);\n  console.log(`\\nQuery Phrase: \"${phrase2}\"`);\n  console.log(`Matching Documents: ${phraseHits2.length} found`);\n  phraseHits2.forEach(h => console.log(`  -> Doc ${h.docId}: \"${h.text}\"`));\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 6. Tiered Retrieval & Champion Lists\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 6: Tiered Indexes & Champion Lists');\n  console.log('Tier 1 stores high-authority documents in RAM. Let us query \"consensus\":\\n');\n\n  const champList = engine.championIndex.get('consensu');\n  console.log('  Champion List (Tier 1 Top-2):', champList ? champList.entries.map(e => `Doc ${e.docId}`).join(', ') : 'None');\n\n  const fastPathQuery = engine.search('consensus', { topK: 2, useChampionLists: true });\n  console.log(`  Query: \"consensus\" (requested topK = 2)`);\n  console.log(`  Strategy Selected: [${fastPathQuery.tierUsed}]`);\n  console.log(`  Results:`);\n  fastPathQuery.results.forEach((r, idx) => {\n    console.log(`    ${idx + 1}. Doc ${r.docId} (Score: ${r.score}, PageRank: ${r.staticScore}) -> \"${r.text.slice(0, 60)}...\"`);\n  });\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 7. Production BM25 Relevance Ranking\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 7: Production BM25 Scoring & Ranking');\n  const searchQueries = [\n    'inverted index postings',\n    'distributed replicated consensus',\n    'elasticsearch lucene shards'\n  ];\n\n  for (const q of searchQueries) {\n    console.log(`\\n\ud83d\udd0e Query: \"${q}\"`);\n    const res = engine.search(q, { topK: 3, useChampionLists: false });\n    console.log(`   Matched ${res.totalCandidates} candidates. Top ranked results:`);\n    res.results.forEach((r, idx) => {\n      console.log(`   [#${idx + 1}] Score: ${r.score} | Doc ${r.docId}`);\n      console.log(`        \"${r.text}\"`);\n    });\n  }\n\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // 8. Arbitrary Scale Batch Ingestion\n  // \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  printSection('PHASE 8: Arbitrary Scale Batch Ingestion (addDocuments)');\n  console.log('Demonstrating dynamic scaling across any number of documents...\\n');\n\n  const batchDocs = [];\n  const systemTerms = ['kafka', 'redis', 'dynamodb', 'cassandra', 'zookeeper', 'etcd'];\n  for (let i = 100; i < 150; i++) {\n    const primary = systemTerms[i % systemTerms.length];\n    batchDocs.push({\n      id: i,\n      text: `System record ${i} benchmarks ${primary} cluster throughput with partitioned logs and distributed replication.`,\n      staticScore: Number((0.5 + (i % 50) / 100).toFixed(2))\n    });\n  }\n\n  const startTime = Date.now();\n  engine.addDocuments(batchDocs);\n  const elapsed = Date.now() - startTime;\n\n  console.log(`Indexed ${batchDocs.length} additional documents in ${elapsed}ms.`);\n  console.log(`Total corpus size: ${engine.docCount} documents.`);\n  console.log(`Total indexed terms: ${engine.totalDocLength} tokens.`);\n  console.log(`Updated average document length: ${engine.avgDocLength.toFixed(2)} tokens.`);\n\n  const batchSearch = engine.search('kafka cluster', { topK: 3 });\n  console.log(`\\nQuery \"kafka cluster\" across expanded corpus (${batchSearch.totalCandidates} candidates):`);\n  batchSearch.results.forEach((r, idx) => {\n    console.log(`  #${idx + 1} Doc ${r.docId} [Score: ${r.score}] \"${r.text.slice(0, 70)}...\"`);\n  });\n\n  printSection('\ud83c\udf89 LAB COMPLETED SUCCESSFULLY');\n  console.log('All search engine primitives executed and verified.');\n}\n\nif (require.main === module) {\n  runLab().catch(console.error);\n}\n\nmodule.exports = { runLab };"
    }
},
"sliding-window-rate-limiter": {
    "id": "sliding-window-rate-limiter",
    "title": "Sliding Window Rate Limiter",
    "primarySlug": "sliding-window-rate-limiter",
    "summary": "An in-memory rate limiter that records timestamp logs per client and provides precise allow, reject, and retry-after responses.",
    "files": {
      "README.md": "# Sliding Window Rate Limiter\n\nThis limiter keeps recent request timestamps per key and rejects calls once a key has too many hits inside the active rolling window.\n\nAvoids boundary burst vulnerability seen in fixed-window limiters.",
      "limiter.js": "class SlidingWindowRateLimiter {\n  constructor(maxRequests = 5, windowMs = 60000) {\n    this.maxRequests = maxRequests;\n    this.windowMs = windowMs;\n    this.hitsByKey = new Map();\n  }\n\n  allow(key, now = Date.now()) {\n    const threshold = now - this.windowMs;\n    let timestamps = this.hitsByKey.get(key) || [];\n\n    timestamps = timestamps.filter(t => t > threshold);\n\n    if (timestamps.length < this.maxRequests) {\n      timestamps.push(now);\n      this.hitsByKey.set(key, timestamps);\n      return {\n        allowed: true,\n        remaining: this.maxRequests - timestamps.length,\n        retryAfterMs: 0\n      };\n    }\n\n    const oldest = timestamps[0];\n    const retryAfterMs = Math.max(0, oldest + this.windowMs - now);\n    this.hitsByKey.set(key, timestamps);\n\n    return {\n      allowed: false,\n      remaining: 0,\n      retryAfterMs\n    };\n  }\n}\n\nmodule.exports = { SlidingWindowRateLimiter };",
      "demo.js": "const { SlidingWindowRateLimiter } = require(\"./limiter\");\n\nconst limiter = new SlidingWindowRateLimiter(3, 5000);\nconst client = \"user_ip_127.0.0.1\";\nconst start = 1700000000000;\n\nconsole.log(\"Send 5 requests within 2 seconds:\");\nfor (let i = 0; i < 5; i++) {\n  const t = start + i * 500;\n  const res = limiter.allow(client, t);\n  console.log(\"t+\" + (i * 500) + \"ms -> Allowed: \" + res.allowed + \", Remaining: \" + res.remaining + \", RetryAfter: \" + res.retryAfterMs + \"ms\");\n}\n\nconsole.log(\"Wait until rolling window slides (t+5500ms):\");\nconst resAfter = limiter.allow(client, start + 5500);\nconsole.log(\"t+5500ms -> Allowed: \" + resAfter.allowed + \", Remaining: \" + resAfter.remaining);"
    }
  },
  "lease-leader-election": {
    "id": "lease-leader-election",
    "title": "Lease-Based Leader Election with Fencing Tokens",
    "primarySlug": "leader-election",
    "summary": "Leader election simulation with bounded leases, heartbeats, and monotonically increasing fencing tokens to prevent split-brain write hazards.",
    "files": {
      "README.md": "# Lease Leader Election with Fencing Tokens\n\nDemonstrates distributed leader leases and why **fencing tokens** are mandatory to prevent split-brain corruption during garbage collection pauses.",
      "coordinator.js": "class LeaseCoordinator {\n  constructor(leaseDurationMs = 3000) {\n    this.leaseDurationMs = leaseDurationMs;\n    this.currentLeader = null;\n    this.leaseExpiresAt = 0;\n    this.tokenCounter = 0;\n  }\n\n  acquireOrRenew(candidateId, now = Date.now()) {\n    if (this.currentLeader === candidateId) {\n      this.leaseExpiresAt = now + this.leaseDurationMs;\n      return { success: true, leader: candidateId, fencingToken: this.tokenCounter, expiresAt: this.leaseExpiresAt };\n    }\n\n    if (now > this.leaseExpiresAt) {\n      this.currentLeader = candidateId;\n      this.leaseExpiresAt = now + this.leaseDurationMs;\n      this.tokenCounter += 1;\n      return { success: true, leader: candidateId, fencingToken: this.tokenCounter, expiresAt: this.leaseExpiresAt };\n    }\n\n    return { success: false, currentLeader: this.currentLeader, expiresAt: this.leaseExpiresAt };\n  }\n}\n\nclass StorageServer {\n  constructor() {\n    this.highestFencingToken = 0;\n    this.records = [];\n  }\n\n  write(fencingToken, data) {\n    if (fencingToken < this.highestFencingToken) {\n      throw new Error(\"Split-brain detected! Rejecting write with stale fencing token \" + fencingToken + \" (Current: \" + this.highestFencingToken + \")\");\n    }\n    this.highestFencingToken = fencingToken;\n    this.records.push({ data, fencingToken });\n    return true;\n  }\n}\n\nmodule.exports = { LeaseCoordinator, StorageServer };",
      "demo.js": "const { LeaseCoordinator, StorageServer } = require(\"./coordinator\");\n\nconst coord = new LeaseCoordinator(2000);\nconst storage = new StorageServer();\n\nconsole.log(\"1. Node A acquires leader lease:\");\nconst leaseA = coord.acquireOrRenew(\"Node-A\", 1000);\nconsole.log(leaseA);\nstorage.write(leaseA.fencingToken, \"Node-A initial payload\");\n\nconsole.log(\"2. Node A experiences a long GC pause. Lease expires.\");\nconsole.log(\"   Node B steps in and claims leadership:\");\nconst leaseB = coord.acquireOrRenew(\"Node-B\", 4500);\nconsole.log(leaseB);\nstorage.write(leaseB.fencingToken, \"Node-B payload\");\n\nconsole.log(\"3. Node A wakes up and attempts to write with its old token:\");\ntry {\n  storage.write(leaseA.fencingToken, \"Node-A delayed ghost write\");\n} catch (err) {\n  console.log(\"   PROTECTION SUCCEEDED: \" + err.message);\n}"
    }
  },
  "write-ahead-log": {
    "id": "write-ahead-log",
    "title": "Write-Ahead Log (WAL) & Crash Recovery",
    "primarySlug": "database-wal-and-recovery",
    "summary": "An append-only write-ahead log system that records operations before memory updates and replays logs to recover state after sudden process termination.",
    "files": {
      "README.md": "# Write-Ahead Log (WAL) Engine\n\nThe fundamental pattern of databases (Postgres, SQLite, MySQL InnoDB, Kafka).\n\n### Principle:\nEvery mutation is fsynced sequentially to disk **before** modifying the in-memory data structure. Upon crash, replaying the WAL reconstructs the exact state.\n\n### Features:\n- **Real file I/O**: Uses Node.js `fs` module with `fsync()` for durability\n- **CRC32 checksums**: Each record includes a checksum to detect torn writes\n- **Torn-write detection**: Identifies incomplete writes at recovery time\n- **LSN tracking**: Monotonically increasing Log Sequence Numbers",
      "wal.js": "const fs = require('fs');\nconst crypto = require('crypto');\n\nclass WriteAheadLogStore {\n  constructor(filePath = './wal.log') {\n    this.filePath = filePath;\n    this.memTable = new Map();\n    this.lastLsn = 0;\n    this.fd = null;\n  }\n\n  // CRC32 checksum for torn-write detection\n  _crc32(data) {\n    const buf = Buffer.isBuffer(data) ? data : Buffer.from(JSON.stringify(data));\n    return crypto.createHash('crc32').update(buf).digest('hex');\n  }\n\n  // Serialize a log record with checksum\n  _serializeRecord(record) {\n    const payload = JSON.stringify(record);\n    const checksum = this._crc32(payload);\n    return JSON.stringify({ ...record, checksum }) + '\\n';\n  }\n\n  // Deserialize and verify a log record\n  _deserializeRecord(line) {\n    try {\n      const record = JSON.parse(line);\n      const { checksum, ...data } = record;\n      const expectedChecksum = this._crc32(JSON.stringify(data));\n      if (checksum !== expectedChecksum) {\n        throw new Error('Checksum mismatch - torn write detected');\n      }\n      return data;\n    } catch (e) {\n      return null; // Skip malformed records\n    }\n  }\n\n  // Open log file for appending\n  open() {\n    this.fd = fs.openSync(this.filePath, 'a');\n  }\n\n  // Close log file\n  close() {\n    if (this.fd !== null) {\n      fs.closeSync(this.fd);\n      this.fd = null;\n    }\n  }\n\n  // Append record to log and fsync before returning\n  appendLogRecord(op, key, value) {\n    this.lastLsn += 1;\n    const record = { lsn: this.lastLsn, op, key, value, timestamp: Date.now() };\n    const serialized = this._serializeRecord(record);\n    \n    // Write to file\n    fs.writeSync(this.fd, serialized);\n    // Fsync to guarantee durability\n    fs.fsyncSync(this.fd);\n    \n    return record;\n  }\n\n  set(key, value) {\n    const record = this.appendLogRecord('SET', key, value);\n    this.memTable.set(key, value);\n    return record.lsn;\n  }\n\n  delete(key) {\n    const record = this.appendLogRecord('DEL', key, null);\n    this.memTable.delete(key);\n    return record.lsn;\n  }\n\n  get(key) {\n    return this.memTable.get(key);\n  }\n\n  // Simulate crash: clear memory but keep log file\n  crashSimulate() {\n    this.memTable.clear();\n    this.lastLsn = 0;\n  }\n\n  // Recover state by replaying WAL\n  recover() {\n    console.log('Starting WAL recovery...');\n    const data = fs.readFileSync(this.filePath, 'utf8');\n    const lines = data.split('\\n').filter(Boolean);\n    let replayed = 0;\n    let skipped = 0;\n\n    for (const line of lines) {\n      const record = this._deserializeRecord(line);\n      if (!record) {\n        skipped++;\n        continue; // Skip torn/corrupted records\n      }\n\n      if (record.op === 'SET') {\n        this.memTable.set(record.key, record.value);\n      } else if (record.op === 'DEL') {\n        this.memTable.delete(record.key);\n      }\n      this.lastLsn = Math.max(this.lastLsn, record.lsn);\n      replayed++;\n    }\n\n    console.log(`Recovery complete: ${replayed} records replayed, ${skipped} skipped (torn writes)`);\n  }\n}\n\nmodule.exports = { WriteAheadLogStore };",
      "demo.js": "const { WriteAheadLogStore } = require('./wal');\nconst fs = require('fs');\n\n// Clean up previous log\nif (fs.existsSync('./wal.log')) fs.unlinkSync('./wal.log');\n\nconst db = new WriteAheadLogStore('./wal.log');\ndb.open();\n\nconsole.log('=== WAL Demo ===');\ndb.set('user:101', { name: 'Alice', balance: 500 });\ndb.set('user:102', { name: 'Bob', balance: 250 });\ndb.set('user:101', { name: 'Alice', balance: 650 });\ndb.delete('user:102');\n\nconsole.log('State before crash:', db.get('user:101'));\nconsole.log('Log file size:', fs.statSync('./wal.log').size, 'bytes');\n\n// Simulate crash\nconsole.log('\\nProcess crash! Memory wiped.');\ndb.crashSimulate();\nconsole.log('Query after crash:', db.get('user:101')); // null\n\n// Recover\nconsole.log('\\nReplaying WAL from disk...');\ndb.recover();\nconsole.log('Query after recovery:', db.get('user:101')); // { name: 'Alice', balance: 650 }\n\ndb.close();"
    }
  },
  "gossip-protocol": {
    "id": "gossip-protocol",
    "title": "Push-Pull Gossip Protocol Simulation",
    "primarySlug": "gossip-protocol",
    "summary": "An epidemic peer-to-peer state dissemination protocol where nodes periodically exchange versioned state summaries and converge exponentially.",
    "files": {
      "README.md": "# Push-Pull Gossip Protocol\n\nThe peer-to-peer membership and state synchronization mechanism behind Cassandra, Dynamo, and Consul.",
      "gossip.js": "class GossipNode {\n  constructor(id) {\n    this.id = id;\n    this.peers = [];\n    this.state = new Map();\n  }\n\n  addPeer(peer) {\n    this.peers.push(peer);\n  }\n\n  updateLocal(key, value) {\n    const current = this.state.get(key) || { version: 0 };\n    this.state.set(key, { value, version: current.version + 1 });\n  }\n\n  gossipRound() {\n    if (this.peers.length === 0) return;\n    const target = this.peers[Math.floor(Math.random() * this.peers.length)];\n\n    for (const [key, entry] of this.state.entries()) {\n      const targetEntry = target.state.get(key);\n      if (!targetEntry || targetEntry.version < entry.version) {\n        target.state.set(key, Object.assign({}, entry));\n      }\n    }\n\n    for (const [key, entry] of target.state.entries()) {\n      const ourEntry = this.state.get(key);\n      if (!ourEntry || ourEntry.version < entry.version) {\n        this.state.set(key, Object.assign({}, entry));\n      }\n    }\n  }\n}\n\nmodule.exports = { GossipNode };",
      "demo.js": "const { GossipNode } = require(\"./gossip\");\n\nconst nodes = [\"A\", \"B\", \"C\", \"D\", \"E\"].map(id => new GossipNode(id));\nfor (let i = 0; i < nodes.length; i++) {\n  nodes[i].addPeer(nodes[(i + 1) % nodes.length]);\n  nodes[i].addPeer(nodes[(i - 1 + nodes.length) % nodes.length]);\n}\n\nconsole.log(\"Node A receives update: 'leader' = 'Node-E'\");\nnodes[0].updateLocal(\"cluster_leader\", \"Node-E\");\n\nfor (let round = 1; round <= 4; round++) {\n  nodes.forEach(n => n.gossipRound());\n  const status = nodes.map(n => n.id + \":\" + (n.state.get(\"cluster_leader\")?.value || \"?\")).join(\" | \");\n  console.log(\"Round \" + round + \": \" + status);\n}"
    }
  },
  "ttl-cache-reaper": {
    "id": "ttl-cache-reaper",
    "title": "TTL Cache with Active Background Reapers",
    "primarySlug": "ttl-expiration-and-cache-reapers",
    "summary": "An in-memory TTL cache storing absolute expiry timestamps, enforcing passive read expiration, and actively reclaiming expired memory via scheduled sweeps.",
    "files": {
      "README.md": "# TTL Cache with Active Reapers\n\nDual-tier expiration model:\n1. **Passive Expiration**: Rechecks timestamp during `get()`. If expired, evicts immediately and returns `null`.\n2. **Active Reaping**: Periodic background timer that cleans up abandoned keys that are never read.\n\n### Features:\n- Real `setInterval` for automatic background sweeping\n- Passive expiration on read for immediate eviction\n- Configurable sweep interval and TTL\n- Proper cleanup on `destroy()`",
      "cache.js": "class TTLReaperCache {\n  constructor(sweepIntervalMs = 5000) {\n    this.store = new Map();\n    this.sweepIntervalMs = sweepIntervalMs;\n    this.timer = null;\n    this.stats = { sets: 0, gets: 0, hits: 0, misses: 0, sweeps: 0, evicted: 0 };\n    \n    // Start background reaper\n    this._startReaper();\n  }\n\n  _startReaper() {\n    if (this.timer) clearInterval(this.timer);\n    this.timer = setInterval(() => {\n      const evicted = this.sweep();\n      if (evicted > 0) {\n        console.log(`[Reaper] Swept ${evicted} expired keys`);\n      }\n    }, this.sweepIntervalMs);\n    // Allow process to exit even if timer is running\n    if (this.timer.unref) this.timer.unref();\n  }\n\n  set(key, value, ttlMs) {\n    const expiresAt = Date.now() + ttlMs;\n    this.store.set(key, { value, expiresAt });\n    this.stats.sets++;\n  }\n\n  get(key) {\n    this.stats.gets++;\n    const item = this.store.get(key);\n    if (!item) {\n      this.stats.misses++;\n      return null;\n    }\n\n    // Passive expiration\n    if (Date.now() >= item.expiresAt) {\n      this.store.delete(key);\n      this.stats.misses++;\n      this.stats.evicted++;\n      return null;\n    }\n\n    this.stats.hits++;\n    return item.value;\n  }\n\n  sweep() {\n    let evicted = 0;\n    const now = Date.now();\n    for (const [key, item] of this.store.entries()) {\n      if (now >= item.expiresAt) {\n        this.store.delete(key);\n        evicted++;\n      }\n    }\n    this.stats.sweeps++;\n    this.stats.evicted += evicted;\n    return evicted;\n  }\n\n  getStats() {\n    return { ...this.stats, size: this.store.size };\n  }\n\n  destroy() {\n    if (this.timer) {\n      clearInterval(this.timer);\n      this.timer = null;\n    }\n  }\n}\n\nmodule.exports = { TTLReaperCache };",
      "demo.js": "const { TTLReaperCache } = require('./cache');\n\nconsole.log('=== TTL Cache with Active Reaper Demo ===');\n\n// Create cache with 1-second sweep interval\nconst cache = new TTLReaperCache(1000);\n\n// Add some keys with different TTLs\ncache.set('session:short', 'expires-soon', 1500);  // 1.5s\ncache.set('session:long', 'lasts-awhile', 5000);   // 5s\ncache.set('session:tiny', 'almost-instant', 100);   // 100ms\n\nconsole.log('Initial size:', cache.getStats().size);\nconsole.log('Get short-lived key:', cache.get('session:short'));\n\n// Wait for tiny key to expire\nsetTimeout(() => {\n  console.log('\\nAfter 200ms:');\n  console.log('  Tiny key (should be null):', cache.get('session:tiny'));\n  console.log('  Short key (should exist):', cache.get('session:short'));\n  console.log('  Stats:', cache.getStats());\n}, 200);\n\n// Wait for reaper to run\nsetTimeout(() => {\n  console.log('\\nAfter 2s (reaper has run):');\n  console.log('  Size:', cache.getStats().size);\n  console.log('  Short key (expired):', cache.get('session:short'));\n  console.log('  Long key (still alive):', cache.get('session:long'));\n  console.log('  Stats:', cache.getStats());\n  cache.destroy();\n}, 2500);"
    }
  },
  "lru-cache": {
    "id": "lru-cache",
    "title": "LRU Cache (Doubly Linked List + Hash Map)",
    "primarySlug": "cache-eviction-policies",
    "summary": "An O(1) Least Recently Used cache implementation combining a doubly linked list for order tracking with a hash map for constant-time key lookups.",
    "files": {
      "README.md": "# O(1) LRU Cache\n\nGuarantees $O(1)$ time complexity for both `get(key)` and `put(key, value)` operations using:\n- **Doubly Linked List**: Node ordering by access recency.\n- **Hash Map**: Direct node pointer reference by key.",
      "lru.js": "class Node {\n  constructor(key, val) {\n    this.key = key;\n    this.val = val;\n    this.prev = null;\n    this.next = null;\n  }\n}\n\nclass LRUCache {\n  constructor(capacity) {\n    this.capacity = capacity;\n    this.map = new Map();\n    this.head = new Node(null, null);\n    this.tail = new Node(null, null);\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n  }\n\n  _remove(node) {\n    node.prev.next = node.next;\n    node.next.prev = node.prev;\n  }\n\n  _insertHead(node) {\n    node.next = this.head.next;\n    node.prev = this.head;\n    this.head.next.prev = node;\n    this.head.next = node;\n  }\n\n  get(key) {\n    if (!this.map.has(key)) return -1;\n    const node = this.map.get(key);\n    this._remove(node);\n    this._insertHead(node);\n    return node.val;\n  }\n\n  put(key, val) {\n    if (this.map.has(key)) {\n      const node = this.map.get(key);\n      node.val = val;\n      this._remove(node);\n      this._insertHead(node);\n      return;\n    }\n\n    if (this.map.size >= this.capacity) {\n      const lru = this.tail.prev;\n      this._remove(lru);\n      this.map.delete(lru.key);\n    }\n\n    const newNode = new Node(key, val);\n    this._insertHead(newNode);\n    this.map.set(key, newNode);\n  }\n}\n\nmodule.exports = { LRUCache };",
      "demo.js": "const { LRUCache } = require(\"./lru\");\n\nconst cache = new LRUCache(2);\ncache.put(\"a\", 1);\ncache.put(\"b\", 2);\nconsole.log(\"Get a:\", cache.get(\"a\"));\ncache.put(\"c\", 3);\nconsole.log(\"Get b (evicted):\", cache.get(\"b\"));\nconsole.log(\"Get c:\", cache.get(\"c\"));"
    }
  },
  "snowflake-id-generator": {
    "id": "snowflake-id-generator",
    "title": "Twitter Snowflake 64-Bit ID Generator",
    "primarySlug": "snowflake-id-design",
    "summary": "A 64-bit unique ID generator packing epoch milliseconds, machine worker IDs, and an incremental sequence into a monotonically sortable integer.",
    "files": {
      "README.md": "# Snowflake 64-bit ID Generator\n\nThe distributed ID layout popularized by Twitter:\n```\n1 bit unused | 41 bits timestamp ms | 10 bits worker ID (1024 workers) | 12 bits sequence (4096 IDs/ms)\n```\nEnables up to **4.096 million ordered IDs per machine per second** without inter-node coordination.",
      "snowflake.js": "class SnowflakeGenerator {\n  constructor(workerId, datacenterId = 0, epoch = 1609459200000n) {\n    this.workerId = BigInt(workerId);\n    this.datacenterId = BigInt(datacenterId);\n    this.epoch = epoch;\n\n    this.workerIdBits = 5n;\n    this.datacenterIdBits = 5n;\n    this.sequenceBits = 12n;\n\n    this.maxWorkerId = -1n ^ (-1n << this.workerIdBits);\n    this.maxSequence = -1n ^ (-1n << this.sequenceBits);\n\n    this.workerIdShift = this.sequenceBits;\n    this.datacenterIdShift = this.sequenceBits + this.workerIdBits;\n    this.timestampShift = this.sequenceBits + this.workerIdBits + this.datacenterIdBits;\n\n    this.sequence = 0n;\n    this.lastTimestamp = -1n;\n  }\n\n  nextId() {\n    let now = BigInt(Date.now());\n\n    if (now < this.lastTimestamp) {\n      throw new Error(\"Clock moved backwards! Refusing to generate ID.\");\n    }\n\n    if (now === this.lastTimestamp) {\n      this.sequence = (this.sequence + 1n) & this.maxSequence;\n      if (this.sequence === 0n) {\n        while (BigInt(Date.now()) <= this.lastTimestamp) {}\n        now = BigInt(Date.now());\n      }\n    } else {\n      this.sequence = 0n;\n    }\n\n    this.lastTimestamp = now;\n\n    return (\n      ((now - this.epoch) << this.timestampShift) |\n      (this.datacenterId << this.datacenterIdShift) |\n      (this.workerId << this.workerIdShift) |\n      this.sequence\n    );\n  }\n}\n\nmodule.exports = { SnowflakeGenerator };",
      "demo.js": "const { SnowflakeGenerator } = require(\"./snowflake\");\n\nconst gen = new SnowflakeGenerator(3, 1);\nconsole.log(\"Generate 5 unique IDs:\");\nfor (let i = 0; i < 5; i++) {\n  const id = gen.nextId();\n  console.log(\"ID \" + (i + 1) + \": \" + id.toString());\n}"
    }
  },
  "keyset-pagination-cursors": {
    "id": "keyset-pagination-cursors",
    "title": "Keyset (Cursor) Pagination vs SQL OFFSET",
    "primarySlug": "keyset-pagination",
    "summary": "Demonstrates how cursor predicates (WHERE id > :cursor LIMIT N) deliver stable, deterministic results under concurrent inserts while OFFSET scans drift.",
    "files": {
      "README.md": "# Keyset Pagination Cursors vs OFFSET\n\n### The Problem with `OFFSET 100000`:\nThe database must scan 100,000 rows into memory only to discard them ($O(N)$ execution time). Furthermore, if a new row is inserted between requests, users see duplicate records.\n\n### The Keyset Solution:\nUses indexed comparison: `WHERE (created_at, id) < (:last_date, :last_id) ORDER BY created_at DESC, id DESC LIMIT 20` ($O(1)$ b-tree seek).",
      "pagination.js": "class DatabaseDataset {\n  constructor(initialRows) {\n    this.rows = [...initialRows];\n  }\n\n  insert(row) {\n    this.rows.unshift(row);\n  }\n\n  offsetPage(pageNumber, pageSize) {\n    const offset = (pageNumber - 1) * pageSize;\n    return this.rows.slice(offset, offset + pageSize);\n  }\n\n  keysetPage(afterCursorId, pageSize) {\n    let startIndex = 0;\n    if (afterCursorId !== null) {\n      const idx = this.rows.findIndex(r => r.id === afterCursorId);\n      startIndex = idx !== -1 ? idx + 1 : 0;\n    }\n    const pageRows = this.rows.slice(startIndex, startIndex + pageSize);\n    const nextCursor = pageRows.length > 0 ? pageRows[pageRows.length - 1].id : null;\n    return { rows: pageRows, nextCursor };\n  }\n}\n\nmodule.exports = { DatabaseDataset };",
      "demo.js": "const { DatabaseDataset } = require(\"./pagination\");\n\nconst dataset = new DatabaseDataset([\n  { id: 10, title: \"Post 10\" },\n  { id: 9, title: \"Post 9\" },\n  { id: 8, title: \"Post 8\" },\n  { id: 7, title: \"Post 7\" },\n  { id: 6, title: \"Post 6\" }\n]);\n\nconst offsetP1 = dataset.offsetPage(1, 2);\nconst cursorP1 = dataset.keysetPage(null, 2);\nconsole.log(\"Page 1 items:\", offsetP1.map(p => p.id));\n\ndataset.insert({ id: 11, title: \"Post 11\" });\n\nconst offsetP2 = dataset.offsetPage(2, 2);\nconsole.log(\"OFFSET Page 2 items:\", offsetP2.map(p => p.id), \"(Post 9 duplicate)\");\n\nconst cursorP2 = dataset.keysetPage(cursorP1.nextCursor, 2);\nconsole.log(\"Keyset Page 2 items:\", cursorP2.rows.map(p => p.id), \"(Clean, no duplicate)\");"
    }
  }
};
